                        ]},
                        { key: 'pokayoke', labelKey: 'dec_pokayoke', options: [
                            { value: 'one_device', labelKey: 'opt_one_device', cost: 15, oee: 2, lt: 0, wip: 0, defect: -300, resist: 2 },
