                            { value: 'none', labelKey: 'opt_no_daily', cost: 0, oee: -2, lt: 1, wip: 0.2, defect: 100, resist: -5 },
                            { value: 'gemba', labelKey: 'opt_gemba', cost: 8, oee: 2, lt: -0.5, wip: -0.05, defect: -80, resist: 5 },
                            { value: 'tiered', labelKey: 'opt_tiered', cost: 18, oee: 4, lt: -1, wip: -0.1, defect: -150, resist: 10 }
                        ]},
                        { key: 'kaizenStructure', labelKey: 'dec_kaizen', options: [
                            { value: 'adhoc', labelKey: 'opt_adhoc', cost: 3, oee: 0.5, lt: -0.2, wip: 0, defect: -30, resist: 0 },
                            { value: 'monthly_events', labelKey: 'opt_monthly_kaizen', cost: 12, oee: 2, lt: -0.5, wip: -0.05, defect: -80, resist: 5 },
                            { value: 'worker_led', labelKey: 'opt_worker_led', cost: 20, oee: 4, lt: -1, wip: -0.1, defect: -200, resist: 12 }
