                        { key: 'crossTraining', labelKey: 'dec_cross_training', options: [
                            { value: 'specialists', labelKey: 'opt_specialists', cost: 0, oee: 0, lt: 0, wip: 0, defect: 0, resist: -3 },
                            { value: 'two_process', labelKey: 'opt_two_process', cost: 10, oee: 2, lt: -0.5, wip: 0, defect: -50, resist: 5 },
