                        ]},
                        { key: 'metricsChange', labelKey: 'dec_metrics_change', options: [
                            { value: 'keep_utilization', labelKey: 'opt_keep_util', cost: 0, oee: -3, lt: 1, wip: 0.2, defect: 100, resist: -10 },
                            { value: 'replace_with_lean', labelKey: 'opt_lean_metrics', cost: 10, oee: 4, lt: -1, wip: -0.15, defect: -150, resist: 15 }
