                }
            ];
        }

        initialize(state) {
            var _fresh = !state.history || state.history.length === 0;
            if (_fresh || !state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    oee: 31,
                    leadTime: 18,
                    wip: 4.2,
                    defectRate: 4200,
                    budgetRemaining: 480,
                    resistanceJorge: 35,
                    communicationR1: 'none',
                    sustainabilityR2: 'one_time',
                    smedDone: false,
                    oeeHistory: [],
                    leadTimeHistory: [],
                    wipHistory: [],
                    defectHistory: [],
                    lpiScore: 0
                };
            }
            if (_fresh || !state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._updateBriefing(state);
            this._updateKpiColors();
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var roundTitle = window.mySimulation.t(round.titleKey);
                var roundBriefing = window.mySimulation.t(round.briefingKey);
                briefEl.innerHTML = '<strong>' + roundTitle + '</strong><br><br>' + roundBriefing;
            }
            var container = document.getElementById('decisionsContainer');
            if (container) {
                var html = '';
                for (var i = 0; i < round.decisions.length; i++) {
                    var dec = round.decisions[i];
                    var label = window.mySimulation.t(dec.labelKey);
                    html += '<div class="lean-sim-decision-group">';
                    html += '<label for="dec_' + dec.key + '">' + label + '</label>';
                    html += '<select id="dec_' + dec.key + '">';
                    html += '<option value="">-- ' + window.mySimulation.t('select_option') + ' --</option>';
                    for (var j = 0; j < dec.options.length; j++) {
                        var opt = dec.options[j];
                        html += '<option value="' + opt.value + '">' + window.mySimulation.t(opt.labelKey) + ' ($' + opt.cost + 'K)</option>';
                    }
                    html += '</select></div>';
                }
                container.innerHTML = html;
            }
            var eventPanel = document.getElementById('eventPanel');
            if (eventPanel) eventPanel.style.display = 'none';
        }

        validateDecisions(decisions) {
            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var totalCost = 0;
            for (var i = 0; i < round.decisions.length; i++) {
                var dec = round.decisions[i];
                var selectEl = document.getElementById('dec_' + dec.key);
                if (!selectEl || !selectEl.value) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('select_all_warning'), 'warning'
                    );
                    return false;
                }
                decisions[dec.key] = selectEl.value;
                for (var j = 0; j < dec.options.length; j++) {
                    if (dec.options[j].value === selectEl.value) {
                        totalCost += dec.options[j].cost;
                        break;
                    }
                }
            }
            var ds = window.mySimulation.state.domainState;
            if (totalCost > ds.budgetRemaining) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }
            decisions._totalCost = totalCost;
            return true;
        }

        calculateResults(state) {
            var ds = state.domainState;
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var deltaOee = 0;
            var deltaLt = 0;
            var deltaWip = 0;
            var deltaDefect = 0;
            var deltaResist = 0;
            var totalCost = 0;

            for (var i = 0; i < round.decisions.length; i++) {
                var dec = round.decisions[i];
                var chosen = d[dec.key];
                for (var j = 0; j < dec.options.length; j++) {
                    var opt = dec.options[j];
                    if (opt.value === chosen) {
                        deltaOee += opt.oee;
                        deltaLt += opt.lt;
                        deltaWip += opt.wip;
                        deltaDefect += opt.defect;
                        deltaResist += opt.resist;
                        totalCost += opt.cost;
                        break;
                    }
                }
            }

            if (roundIdx === 0 && d.communication) {
                ds.communicationR1 = d.communication;
            }
            if (roundIdx === 1 && d.sustainability) {
                ds.sustainabilityR2 = d.sustainability;
            }
            if (roundIdx === 3) {
                ds.smedDone = true;
            }

            var eventMsg = '';
            if (roundIdx === 1) {
                if (ds.communicationR1 === 'none' || ds.communicationR1 === 'general') {
                    eventMsg = window.mySimulation.t('event_strike');
                    deltaOee -= 3;
                    deltaDefect += 200;
                    deltaResist -= 8;
                }
            }
            if (roundIdx === 2) {
                deltaOee -= 5;
                deltaLt += 0.5;
                eventMsg = window.mySimulation.t('event_valley');
                if (d.kanbanType !== 'two_card') {
                    eventMsg += '<br>' + window.mySimulation.t('event_defect_escape');
                    deltaDefect += 300;
                    deltaOee -= 2;
                }
            }
            if (roundIdx === 3) {
                if (ds.oee < 45) {
                    eventMsg = window.mySimulation.t('event_breakdown');
                    deltaOee -= 4;
                    deltaLt += 1;
                }
            }
            if (roundIdx === 4) {
                eventMsg = window.mySimulation.t('event_volume_surge');
                if (ds.resistanceJorge > 60) {
                    deltaOee += 2;
                } else {
                    deltaOee -= 2;
                    deltaLt += 0.5;
                    deltaDefect += 100;
                }
            }

            var resistFactor = ds.resistanceJorge / 100;
            deltaOee = deltaOee * (0.5 + 0.5 * resistFactor);
            deltaLt = deltaLt * (0.5 + 0.5 * resistFactor);
            deltaWip = deltaWip * (0.5 + 0.5 * resistFactor);
            deltaDefect = deltaDefect * (0.5 + 0.5 * resistFactor);

            if (roundIdx === 1 && ds.sustainabilityR2 === 'one_time') {
                deltaOee *= 0.6;
            }
            if (roundIdx === 4 && !ds.smedDone && d.batchSize === '100') {
                deltaOee -= 5;
                deltaLt += 2;
                eventMsg += '<br>' + window.mySimulation.t('event_no_smed_warning');
            }

            ds.oee = Math.max(10, Math.min(95, ds.oee + deltaOee));
            ds.leadTime = Math.max(1, Math.min(25, ds.leadTime + deltaLt));
            ds.wip = Math.max(0.1, Math.min(6, ds.wip + deltaWip));
            ds.defectRate = Math.max(20, Math.min(6000, ds.defectRate + deltaDefect));
            ds.resistanceJorge = Math.max(0, Math.min(100, ds.resistanceJorge + deltaResist));
            ds.budgetRemaining = Math.max(0, ds.budgetRemaining - totalCost);

            var wipReduction = 4.2 - ds.wip;
            if (wipReduction > 0) {
                var cashBack = Math.round(wipReduction * 12);
                ds.budgetRemaining += cashBack * 0.1;
            }
            if (ds.oee > (31 + 5 * (roundIdx + 1))) {
                ds.budgetRemaining += 15;
            }

            ds.budgetRemaining = Math.round(ds.budgetRemaining * 10) / 10;
            ds.oee = Math.round(ds.oee * 10) / 10;
            ds.leadTime = Math.round(ds.leadTime * 10) / 10;
            ds.wip = Math.round(ds.wip * 100) / 100;
            ds.defectRate = Math.round(ds.defectRate);

            ds.oeeHistory.push(ds.oee);
            ds.leadTimeHistory.push(ds.leadTime);
            ds.wipHistory.push(ds.wip);
            ds.defectHistory.push(ds.defectRate);

            if (roundIdx === 5) {
                var oeeScore = Math.min(1, Math.max(0, (ds.oee - 31) / (65 - 31)));
                var ltScore = Math.min(1, Math.max(0, (18 - ds.leadTime) / (18 - 5)));
                var wipScore = Math.min(1, Math.max(0, (4.2 - ds.wip) / (4.2 - 1.0)));
                var defectScore = Math.min(1, Math.max(0, (4200 - ds.defectRate) / (4200 - 1000)));
                ds.lpiScore = Math.round(((oeeScore * 0.3) + (ltScore * 0.3) + (wipScore * 0.2) + (defectScore * 0.2)) * 100);
                if (wipReduction > 2.0) ds.lpiScore += 5;
                ds.lpiScore = Math.min(100, ds.lpiScore);
            }

            if (eventMsg) {
                var eventPanel = document.getElementById('eventPanel');
                var eventText = document.getElementById('eventText');
                if (eventPanel && eventText) {
                    eventPanel.style.display = 'block';
                    eventText.innerHTML = eventMsg;
                }
            }

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
                self._updateKpiColors();
            }, 500);

            return {
                period: state.currentPeriod,
                oee: ds.oee,
                leadTime: ds.leadTime,
                wip: ds.wip,
                defectRate: ds.defectRate,
                budgetSpent: totalCost,
                budgetRemaining: ds.budgetRemaining,
                resistance: ds.resistanceJorge,
                lpi: ds.lpiScore
            };
        }

