        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = last.results || {};
            var oeeScore = Math.min(1, Math.max(0, (ds.oee - 31) / (65 - 31)));
            var ltScore = Math.min(1, Math.max(0, (18 - ds.leadTime) / (18 - 5)));
            var wipScore = Math.min(1, Math.max(0, (4.2 - ds.wip) / (4.2 - 1.0)));
            var defectScore = Math.min(1, Math.max(0, (4200 - ds.defectRate) / (4200 - 1000)));
            var lpi = Math.round(((oeeScore * 0.3) + (ltScore * 0.3) + (wipScore * 0.2) + (defectScore * 0.2)) * 100);
            var wipReduction = 4.2 - (ds.wip !== undefined ? ds.wip : 4.2);
            if (wipReduction > 2.0) lpi += 5;
            lpi = Math.min(100, lpi);

            var performance = 'Needs Improvement';
            if (lpi >= 80) performance = 'World-Class Lean Leader';
            else if (lpi >= 60) performance = 'Effective Lean Practitioner';
            else if (lpi >= 40) performance = 'Developing Lean Capability';

            var insights = [];
            if (oeeScore < 0.5) insights.push(window.mySimulation.t('insight_oee_low'));
            if (ltScore < 0.5) insights.push(window.mySimulation.t('insight_lt_high'));
            if (wipScore < 0.5) insights.push(window.mySimulation.t('insight_wip_high'));
            if (defectScore < 0.5) insights.push(window.mySimulation.t('insight_defect_high'));
            if (lpi >= 70) insights.push(window.mySimulation.t('insight_strong'));

            return {
                lpiScore: lpi,
                finalOee: ds.oee,
                finalLeadTime: ds.leadTime,
                finalWip: ds.wip,
                finalDefectRate: ds.defectRate,
                performance: performance,
                insights: insights
            };
        }

